def source_numpy(t):
    a = np.abs(np.asarray(t, dtype=np.float64))
    if np.any(a > MAXIMUM*(1+4*np.finfo(float).eps)):
        raise ValueError("source approximation is validated only for |t| <= sqrt(40)")
    interval = np.minimum((a/MAXIMUM*SEGMENTS).astype(np.int32), SEGMENTS-1)
    z = 2*a/MAXIMUM*SEGMENTS-2*interval-1
    coefficients = COEFFICIENTS[interval]
    b1, b2 = np.zeros_like(a), np.zeros_like(a)
    for j in range(DEGREE, 0, -1):
        b0 = 2*z*b1-b2+coefficients[...,j]
        b2, b1 = b1, b0
    return z*b1-b2+coefficients[...,0]

def validate_source(n=100003):
    from scipy.special import kv, gamma
    a = np.linspace(0, MAXIMUM, n)
    reference = np.empty_like(a)
    reference[0] = 1/math.sqrt(math.pi)
    reference[1:] = np.sqrt(a[1:])*kv(.25,a[1:]**2)/(2**1.25*math.sqrt(math.pi)*gamma(1.25))
    errors = np.abs(source_numpy(a)-reference)
    return dict(dense_grid_points=n, max_absolute_difference_scipy=float(errors.max()),
                worst_t=float(a[errors.argmax()]), endpoint_error=float(errors[0]),
                generation_decimal_digits=80, segments=SEGMENTS, degree=DEGREE,
                max_abs_t=MAXIMUM)

if __name__ == "__main__":
    import json
    print(json.dumps(validate_source(), indent=2))
